// ============================================
// EASTGATE ACADEMY — SHARED REPORT CARD GENERATOR
// Used by both the parent portal's single download
// and the admin bulk generation tool, so every report
// card looks identical no matter where it's generated.
// ============================================

const EA_LOGO_BASE64 = "data:image/png;base64,";

const EA_PRIMARY = [217, 78, 42];   // brand orange
const EA_MAROON  = [122, 30, 10];   // brand dark maroon
const EA_LIGHT   = [253, 240, 236]; // alternating row tint

/**
 * Determines a color for a grade badge, handling both letter grades
 * (A/B/C/D/F, used when teachers enter results manually) and the
 * numeric GES 1-9 scale (used in bulk-imported report cards).
 */
function eaGradeColor(grade) {
  const g = String(grade).trim().toUpperCase();
  const letterColors = {
    A: [56, 142, 60], B: [25, 118, 210], C: [245, 124, 0],
    D: [123, 31, 162], F: [198, 40, 40]
  };
  if (letterColors[g]) return letterColors[g];

  const n = parseInt(g, 10);
  if (!isNaN(n)) {
    if (n <= 2) return [56, 142, 60];   // Highest / Higher
    if (n <= 4) return [25, 118, 210];  // High / High Average
    if (n <= 6) return [245, 124, 0];   // Average / Low Average
    return [198, 40, 40];               // Low / Lowest
  }
  return [100, 100, 100];
}

/**
 * Draws one full report card into a given jsPDF document instance.
 * Does NOT call doc.save() — caller decides (single download vs. zip).
 *
 * @param {jsPDF} doc
 * @param {Object} info
 *   studentName, studentId, className, term, academicYear (strings)
 *   results: [{ subject, score, grade, remark }]
 */
function eaBuildReportCard(doc, info) {
  const {
    studentName = 'Student',
    studentId = 'N/A',
    className = 'N/A',
    term = 'N/A',
    academicYear = '2025/2026',
    results = []
  } = info;

  const today = new Date().toLocaleDateString('en-GB', {
    day: 'numeric', month: 'long', year: 'numeric'
  });

  // ---- HEADER BANNER ----
  doc.setFillColor(...EA_PRIMARY);
  doc.rect(0, 0, 210, 36, 'F');

  try {
    doc.addImage(EA_LOGO_BASE64, 'PNG', 14, 6, 24, 24);
  } catch (e) {
    console.warn('Logo failed to embed:', e);
  }

  doc.setTextColor(255, 255, 255);
  doc.setFontSize(19);
  doc.setFont('helvetica', 'bold');
  doc.text('EASTGATE ACADEMY', 44, 15);

  doc.setFontSize(9);
  doc.setFont('helvetica', 'normal');
  doc.text('Near Magna Terris Estates, New Dawhenya, Tema, Ghana', 44, 21.5);
  doc.text('Nurturing Future Leaders', 44, 27);

  // Thin gold-ish accent line under the banner
  doc.setFillColor(...EA_MAROON);
  doc.rect(0, 36, 210, 2, 'F');

  // ---- TITLE ----
  doc.setTextColor(...EA_PRIMARY);
  doc.setFontSize(15);
  doc.setFont('helvetica', 'bold');
  doc.text('STUDENT TERMINAL REPORT', 105, 48, { align: 'center' });

  doc.setDrawColor(...EA_PRIMARY);
  doc.setLineWidth(0.4);
  doc.line(14, 52, 196, 52);

  // ---- STUDENT INFO CARD ----
  doc.setFillColor(...EA_LIGHT);
  doc.roundedRect(14, 58, 182, 26, 2, 2, 'F');

  doc.setTextColor(50, 50, 50);
  doc.setFontSize(10);
  doc.setFont('helvetica', 'normal');

  doc.text('Student Name:', 20, 67);
  doc.setFont('helvetica', 'bold');
  doc.text(studentName, 58, 67);

  doc.setFont('helvetica', 'normal');
  doc.text('Student ID:', 20, 75);
  doc.setFont('helvetica', 'bold');
  doc.text(studentId, 58, 75);

  doc.setFont('helvetica', 'normal');
  doc.text('Class:', 20, 83);
  doc.setFont('helvetica', 'bold');
  doc.text(className, 58, 83);

  doc.setFont('helvetica', 'normal');
  doc.text('Term:', 120, 67);
  doc.setFont('helvetica', 'bold');
  doc.text(term, 155, 67);

  doc.setFont('helvetica', 'normal');
  doc.text('Academic Year:', 120, 75);
  doc.setFont('helvetica', 'bold');
  doc.text(academicYear, 155, 75);

  doc.setFont('helvetica', 'normal');
  doc.text('Date Issued:', 120, 83);
  doc.setFont('helvetica', 'bold');
  doc.text(today, 155, 83);

  // ---- RESULTS TABLE ----
  doc.setTextColor(...EA_PRIMARY);
  doc.setFontSize(12);
  doc.setFont('helvetica', 'bold');
  doc.text('Academic Performance', 14, 94);

  const body = results.length > 0
    ? results.map(r => [r.subject || 'N/A', String(r.score ?? '-'), String(r.grade ?? '-'), r.remark || '-'])
    : [['No results available', '', '', '']];

  doc.autoTable({
    startY: 98,
    head: [['Subject', 'Score', 'Grade', 'Remark']],
    body: body,
    headStyles: {
      fillColor: EA_MAROON,
      textColor: 255,
      fontStyle: 'bold',
      fontSize: 10
    },
    bodyStyles: {
      fontSize: 9.5,
      textColor: [50, 50, 50]
    },
    alternateRowStyles: {
      fillColor: EA_LIGHT
    },
    columnStyles: {
      0: { cellWidth: 65 },
      1: { cellWidth: 30, halign: 'center' },
      2: { cellWidth: 30, halign: 'center', fontStyle: 'bold' },
      3: { cellWidth: 57 }
    },
    didParseCell: function (data) {
      if (data.section === 'body' && data.column.index === 2) {
        const color = eaGradeColor(data.cell.raw);
        data.cell.styles.textColor = color;
      }
    },
    margin: { left: 14, right: 14 }
  });

  let y = doc.lastAutoTable.finalY + 10;

  // ---- GRADING KEY / LEGEND ----
  if (y > 240) { doc.addPage(); y = 20; }

  doc.setFillColor(250, 245, 242);
  doc.setDrawColor(230, 210, 200);
  doc.roundedRect(14, y, 182, 30, 2, 2, 'FD');

  doc.setTextColor(...EA_MAROON);
  doc.setFontSize(9.5);
  doc.setFont('helvetica', 'bold');
  doc.text('GRADING KEY', 20, y + 7);

  doc.setFontSize(7.8);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(70, 70, 70);

  const letterKey = 'Letter Grades:   A = Excellent (80-100)   B = Very Good (70-79)   C = Good (60-69)   D = Average (50-59)   F = Needs Improvement (below 50)';
  const numericKey = 'GES Numeric Scale:   1-2 = Higher/Highest   3-4 = High/High Average   5-6 = Average/Low Average   7-9 = Low/Lowest';

  doc.text(letterKey, 20, y + 14, { maxWidth: 172 });
  doc.text(numericKey, 20, y + 22, { maxWidth: 172 });

  y += 38;

  // ---- SIGNATURE LINES ----
  if (y > 260) { doc.addPage(); y = 20; }

  doc.setDrawColor(150, 150, 150);
  doc.setLineWidth(0.2);
  doc.line(20, y + 12, 85, y + 12);
  doc.line(125, y + 12, 190, y + 12);

  doc.setFontSize(8.5);
  doc.setTextColor(90, 90, 90);
  doc.setFont('helvetica', 'normal');
  doc.text("Class Teacher's Signature", 20, y + 17);
  doc.text("Head Teacher's Signature", 125, y + 17);

  // ---- FOOTER ----
  const footerY = 285;
  doc.setDrawColor(...EA_PRIMARY);
  doc.setLineWidth(0.3);
  doc.line(14, footerY - 6, 196, footerY - 6);

  doc.setTextColor(120, 120, 120);
  doc.setFontSize(7.5);
  doc.setFont('helvetica', 'italic');
  doc.text('This is an official report card generated from the Eastgate Academy portal.', 105, footerY - 1, { align: 'center' });
  doc.text('info@eastgateschool.com  |  0244 506 796  |  eastgateacademy.vercel.app', 105, footerY + 3, { align: 'center' });
}

// Make available globally for both parent and admin pages
window.eaBuildReportCard = eaBuildReportCard;